export type CheckedTarget='js'|'ts'|'rust'|'wasm-core'|'wasm-component'|'python'|'php';
export type PublicationProtocol='legacy-symlink'|'portable-file';
export type CompilerEngine='js'|'ts'|'rust'|'wasm-core';
export type OutputAbi='scalar'|'io-dispatcher';
export type KernelProvider='wasm'|'native'|'both';
export interface Source {readonly module:string;readonly kind:'lean'|'ps';readonly text:string;}
export interface CompileOptions {readonly sources:readonly Source[];readonly entryModule:string;readonly engine?:CompilerEngine;readonly kernel?:KernelProvider;readonly assurance?:'checked'|'ordinary-checked';readonly target?:CheckedTarget;readonly rustToolchainRoot?:string;readonly publicationProtocol?:PublicationProtocol;readonly outputAbi?:OutputAbi;}
export interface CheckedCompilation {readonly status:'accepted';readonly engine:CompilerEngine;readonly target:CheckedTarget;readonly outputAbi:OutputAbi;readonly kernelProviders:readonly ('wasm'|'native')[];readonly compilerSourceClosureDigest:string;readonly source:string;readonly sourceEncoding:'utf8'|'psc1-wasm-hex/1'|'psc1-wasm-component-hex/1';readonly receipt:Readonly<Record<string,unknown>>;readonly logicalAdmission:'accepted';readonly irValidation:string;readonly publication:'not-requested';readonly formalPreservation:'not-provided';}
export interface PublishedCompilation {readonly status:'accepted';readonly engine:CompilerEngine;readonly target:CheckedTarget;readonly outputAbi:OutputAbi;readonly kernelProviders:readonly ('wasm'|'native')[];readonly compilerSourceClosureDigest:string;readonly sourceClosureDigest:string;readonly artifact:string;readonly runtimeArtifact:string;readonly publicationProtocol:PublicationProtocol;readonly durability:'confirmed';readonly generation:string;readonly manifestSha256:string;readonly logicalAdmission:'accepted';readonly receipt:Readonly<Record<string,unknown>>;readonly formalPreservation:'not-provided';}
export interface CompilerMetadata {readonly schema:'psc1-universal-npm-distribution/1';readonly version:string;readonly defaultEngine:'js';readonly defaultKernel:'wasm';readonly compilerSourceClosureDigest:string;readonly leanVersion:'4.35.0';readonly leanCommit:string;readonly engines:Readonly<Record<CompilerEngine,{readonly installed:boolean;readonly kind:string;readonly reason?:string}>>;readonly checkedTargets:readonly CheckedTarget[];readonly publicationProtocols:readonly PublicationProtocol[];readonly candidateTargets:readonly string[];readonly publicationPlatforms:readonly ['linux'];readonly finalCrossPlatformRelease:false;}
export interface KernelResult {readonly schema:'psc1-universal-kernel-result/1';readonly provider:KernelProvider;readonly accepted:boolean;readonly agreement:boolean;readonly admissionsSha256:string;readonly leanVersion:'4.35.0';readonly leanCommit:string;readonly wasmMemoryModel:'linear';readonly results:Readonly<Partial<Record<'wasm'|'native',Readonly<Record<string,unknown>>>>>;}
export function getCompilerMetadata():CompilerMetadata;
export function compile(options:CompileOptions):CheckedCompilation;
export function build(options:CompileOptions&{readonly out:string}):PublishedCompilation;
export function checkCanonicalAdmissions(source:string,options?:{readonly provider?:KernelProvider}):Promise<KernelResult>;
export function compileCandidate(options:Omit<CompileOptions,'target'|'kernel'>&{readonly target:'js'|'ts'|'rust'|'wasm-core'}):Readonly<{status:'candidate-only';engine:CompilerEngine;target:string;compilerSourceClosureDigest:string;candidate:Readonly<Record<string,unknown>>;logicalAdmission:'not-run';publicationAuthority:false}>;

export interface KernelToolchainResult extends Omit<KernelResult,'schema'> {readonly schema:'psc1-independent-kernel-toolchain-result/1';readonly scope:string;}
export function createIndependentKernelToolchain(options?:{readonly root?:string;readonly provider?:KernelProvider}):Promise<Readonly<{metadata:Readonly<Record<string,unknown>>;checkCanonicalAdmissions(source:string):Promise<KernelToolchainResult>}>>;

export function readPublication(options:{readonly out:string;readonly publicationProtocol?:PublicationProtocol}):Readonly<{generation:string;directory:string;manifestSha256:string;target:string;protocol:PublicationProtocol;durability:string;manifest:Readonly<Record<string,unknown>>}>|null;
